package com.yoyo.privatechat;
import android.content.Context;import android.graphics.*;import android.net.Uri;import android.util.Base64;import android.widget.ImageView;import java.io.*;
public final class Avatar{
 public static String fromUri(Context c,Uri uri){try{BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;try(InputStream in=c.getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,opt);}opt.inSampleSize=Math.max(1,Math.max(opt.outWidth,opt.outHeight)/600);opt.inJustDecodeBounds=false;Bitmap b;try(InputStream in=c.getContentResolver().openInputStream(uri)){b=BitmapFactory.decodeStream(in,null,opt);}if(b==null)return "";float s=Math.min(1,600f/Math.max(b.getWidth(),b.getHeight()));Bitmap small=Bitmap.createScaledBitmap(b,Math.max(1,(int)(b.getWidth()*s)),Math.max(1,(int)(b.getHeight()*s)),true);ByteArrayOutputStream out=new ByteArrayOutputStream();small.compress(Bitmap.CompressFormat.JPEG,55,out);if(out.size()>44000){out.reset();Bitmap.createScaledBitmap(small,Math.max(1,small.getWidth()/2),Math.max(1,small.getHeight()/2),true).compress(Bitmap.CompressFormat.JPEG,45,out);}return Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP);}catch(Exception e){return "";}}
 public static void into(ImageView v,String data){try{if(data!=null&&!data.isEmpty()){byte[] b=Base64.decode(data,0);v.setImageBitmap(BitmapFactory.decodeByteArray(b,0,b.length));v.setScaleType(ImageView.ScaleType.CENTER_CROP);return;}}catch(Exception ignored){}v.setImageResource(R.drawable.ic_heart);v.setScaleType(ImageView.ScaleType.CENTER_INSIDE);}
}
